def gen(rng):
    def ser(val, L, R):
        out = []
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]; h += 1
            if u == -1:
                out.append('null')
                continue
            out.append(str(val[u]))
            q.append(L[u]); q.append(R[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def build(n, kind):
        val = [rng.randint(-1000, 1000) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        if kind == 'random':
            slots = [(0, 0), (0, 1)]
            for i in range(1, n):
                j = rng.randrange(len(slots))
                slots[j], slots[-1] = slots[-1], slots[j]
                p, side = slots.pop()
                if side == 0:
                    L[p] = i
                else:
                    R[p] = i
                slots.append((i, 0)); slots.append((i, 1))
        elif kind == 'left':
            for i in range(1, n):
                L[i - 1] = i
        elif kind == 'right':
            for i in range(1, n):
                R[i - 1] = i
        elif kind == 'zigzag':
            for i in range(1, n):
                if i % 2:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
        elif kind == 'complete':
            for i in range(1, n):
                if i % 2:
                    L[(i - 1) // 2] = i
                else:
                    R[(i - 1) // 2] = i
        return ser(val, L, R)

    tests = ['null', '1', '1 2', '1 null 2', '1 2 3', '5 -3 null', '0 0 0 0 0', '1 2 null 3', '4 2 7 1 3 6 9', '-1000 1000 -1000']
    for _ in range(30):
        tests.append(build(rng.randint(1, 12), 'random'))
    tests.append(build(20, 'complete'))
    tests.append(build(40000, 'random'))
    tests.append(build(50000, 'left'))
    tests.append(build(50000, 'right'))
    tests.append(build(50000, 'zigzag'))
    tests.append(build(32767, 'complete'))
    return tests
